package com.yeyamo_mobile.api.interaction_service.application;import com.yeyamo_mobile.api.interaction_service.application.port.InteractionOutboxPort;import com.yeyamo_mobile.api.interaction_service.infrastructure.persistence.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service public class GenericInteractionService{private final GenericInteractionRepository repo;private final InteractionOutboxPort outbox;public GenericInteractionService(GenericInteractionRepository r,InteractionOutboxPort o){repo=r;outbox=o;}@Transactional public GenericInteractionEntity add(GenericInteractionEntity.TargetType target,String id,GenericInteractionEntity.Type type,String user,String body,String channel,String correlation){if(type==GenericInteractionEntity.Type.LIKE||type==GenericInteractionEntity.Type.FAVORITE||type==GenericInteractionEntity.Type.FOLLOW){var existing=repo.findByTargetTypeAndTargetIdAndUserIdAndInteractionType(target,id,user,type);if(existing.isPresent()&&existing.get().status==GenericInteractionEntity.Status.ACTIVE)return existing.get();}if(type==GenericInteractionEntity.Type.COMMENT&&(body==null||body.isBlank()))throw new IllegalArgumentException("Comment body required");if(type==GenericInteractionEntity.Type.REPORT&&(body==null||body.isBlank()))throw new IllegalArgumentException("Report reason required");var x=new GenericInteractionEntity();x.id=UUID.randomUUID();x.targetType=target;x.targetId=id;x.userId=user;x.interactionType=type;x.body=body;x.channel=channel;x.status=type==GenericInteractionEntity.Type.REPORT?GenericInteractionEntity.Status.PENDING_MODERATION:GenericInteractionEntity.Status.ACTIVE;repo.save(x);event(x,correlation);return x;}@Transactional public void remove(GenericInteractionEntity.TargetType target,String id,GenericInteractionEntity.Type type,String user,String correlation){var x=repo.findByTargetTypeAndTargetIdAndUserIdAndInteractionType(target,id,user,type).orElseThrow();if(x.status==GenericInteractionEntity.Status.REMOVED)return;x.status=GenericInteractionEntity.Status.REMOVED;repo.save(x);event(x,correlation);}@Transactional(readOnly=true)public List<GenericInteractionEntity>comments(GenericInteractionEntity.TargetType target,String id){return repo.findByTargetTypeAndTargetIdAndInteractionTypeAndStatusOrderByCreatedAtAsc(target,id,GenericInteractionEntity.Type.COMMENT,GenericInteractionEntity.Status.ACTIVE);}private void event(GenericInteractionEntity x,String c){String prefix=switch(x.targetType){case ARTWORK->"Artwork";case CULTURE_CONTENT->"CultureContent";case CHALLENGE_SUBMISSION,CULTURE_CHALLENGE->"Challenge";case DAILY_WORD->"DailyWord";case ARTISAN->"Artisan";case POST->"Post";};String action=switch(x.interactionType){case LIKE->x.status==GenericInteractionEntity.Status.REMOVED?"LikeRemoved":"Liked";case FAVORITE->x.status==GenericInteractionEntity.Status.REMOVED?"FavoriteRemoved":"Favorited";case COMMENT->"Commented";case SHARE->"Shared";case REPORT->"Reported";case VIEW->"Viewed";case FOLLOW->x.status==GenericInteractionEntity.Status.REMOVED?"Unfollowed":"Followed";};outbox.append(prefix+action,"interaction",x.id.toString(),x.userId,c,Map.of("targetType",x.targetType.name(),"targetId",x.targetId,"userId",x.userId,"interactionType",x.interactionType.name()));}}
